package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"unicode"
	"unicode/utf8"
)

const versionOutput = "sd 1.0.0\n"

type cliOptions struct {
	find            string
	replaceWith     string
	files           []string
	preview         bool
	fixedStrings    bool
	maxReplacements int
	flags           string

	previewSet      bool
	fixedStringsSet bool
	maxSet          bool
	flagsSet        bool
}

type regexFlags struct {
	caseInsensitive bool
	multiLine       bool
	dotMatchesNL    bool
	wordBoundary    bool
}

type fileInput struct {
	path     string
	contents []byte
}

func main() {
	binName := filepath.Base(os.Args[0])
	options, action, err := parseArgs(binName, os.Args[1:])
	switch action {
	case "help-short":
		fmt.Print(shortHelp(binName))
		return
	case "help-long":
		fmt.Print(longHelp(binName))
		return
	case "version":
		fmt.Print(versionOutput)
		return
	}
	if err != nil {
		fmt.Fprint(os.Stderr, err.Error())
		os.Exit(2)
	}

	if runErr := run(options); runErr != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", runErr)
		os.Exit(1)
	}
}

func parseArgs(binName string, args []string) (cliOptions, string, error) {
	var opts cliOptions
	var positionals []string
	stopOptions := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !stopOptions && arg == "--" {
			stopOptions = true
			continue
		}

		if !stopOptions && strings.HasPrefix(arg, "--") && arg != "--" {
			name, value, hasValue := splitLongOption(arg)
			switch name {
			case "help":
				return cliOptions{}, "help-long", nil
			case "version":
				return cliOptions{}, "version", nil
			case "preview":
				if hasValue {
					return cliOptions{}, "", unexpectedArgumentError(binName, arg)
				}
				if opts.previewSet {
					return cliOptions{}, "", duplicateArgumentError(binName, "--preview")
				}
				opts.preview = true
				opts.previewSet = true
			case "fixed-strings":
				if hasValue {
					return cliOptions{}, "", unexpectedArgumentError(binName, arg)
				}
				if opts.fixedStringsSet {
					return cliOptions{}, "", duplicateArgumentError(binName, "--fixed-strings")
				}
				opts.fixedStrings = true
				opts.fixedStringsSet = true
			case "max-replacements":
				if opts.maxSet {
					return cliOptions{}, "", duplicateArgumentError(binName, "--max-replacements <LIMIT>")
				}
				if !hasValue {
					i++
					if i >= len(args) {
						return cliOptions{}, "", missingValueError("--max-replacements <LIMIT>")
					}
					value = args[i]
				}
				parsed, parseErr := parseMaxReplacements(value)
				if parseErr != nil {
					return cliOptions{}, "", invalidMaxReplacementsError(value)
				}
				opts.maxReplacements = parsed
				opts.maxSet = true
			case "flags":
				if opts.flagsSet {
					return cliOptions{}, "", duplicateArgumentError(binName, "--flags <FLAGS>")
				}
				if !hasValue {
					i++
					if i >= len(args) {
						return cliOptions{}, "", missingValueError("--flags <FLAGS>")
					}
					value = args[i]
				}
				opts.flags = value
				opts.flagsSet = true
			default:
				return cliOptions{}, "", unexpectedArgumentError(binName, arg)
			}
			continue
		}

		if !stopOptions && strings.HasPrefix(arg, "-") && arg != "-" {
			shorts := arg[1:]
			for j := 0; j < len(shorts); j++ {
				switch shorts[j] {
				case 'h':
					return cliOptions{}, "help-short", nil
				case 'V':
					return cliOptions{}, "version", nil
				case 'p':
					if opts.previewSet {
						return cliOptions{}, "", duplicateArgumentError(binName, "--preview")
					}
					opts.preview = true
					opts.previewSet = true
				case 'F':
					if opts.fixedStringsSet {
						return cliOptions{}, "", duplicateArgumentError(binName, "--fixed-strings")
					}
					opts.fixedStrings = true
					opts.fixedStringsSet = true
				case 'n':
					if opts.maxSet {
						return cliOptions{}, "", duplicateArgumentError(binName, "--max-replacements <LIMIT>")
					}
					value := shorts[j+1:]
					if value == "" {
						i++
						if i >= len(args) {
							return cliOptions{}, "", missingValueError("--max-replacements <LIMIT>")
						}
						value = args[i]
					}
					parsed, parseErr := parseMaxReplacements(value)
					if parseErr != nil {
						return cliOptions{}, "", invalidMaxReplacementsError(value)
					}
					opts.maxReplacements = parsed
					opts.maxSet = true
					j = len(shorts)
				case 'f':
					if opts.flagsSet {
						return cliOptions{}, "", duplicateArgumentError(binName, "--flags <FLAGS>")
					}
					value := shorts[j+1:]
					if value == "" {
						i++
						if i >= len(args) {
							return cliOptions{}, "", missingValueError("--flags <FLAGS>")
						}
						value = args[i]
					}
					opts.flags = value
					opts.flagsSet = true
					j = len(shorts)
				default:
					return cliOptions{}, "", unexpectedArgumentError(binName, "-"+string(shorts[j]))
				}
			}
			continue
		}

		positionals = append(positionals, arg)
	}

	if len(positionals) < 2 {
		return cliOptions{}, "", missingRequiredArgsError(binName, opts, len(positionals))
	}

	opts.find = positionals[0]
	opts.replaceWith = positionals[1]
	opts.files = positionals[2:]
	return opts, "", nil
}

func run(opts cliOptions) error {
	re, flags, err := compilePattern(opts)
	if err != nil {
		return err
	}

	if len(opts.files) == 0 {
		input, readErr := io.ReadAll(os.Stdin)
		if readErr != nil {
			return formatOSError(readErr)
		}
		output := replaceAll(re, input, opts, flags.wordBoundary)
		_, writeErr := os.Stdout.Write(output)
		if writeErr != nil {
			return formatOSError(writeErr)
		}
		return nil
	}

	inputs, loadErr := loadFiles(opts.files)
	if loadErr != nil {
		return loadErr
	}

	if opts.preview {
		return writePreview(inputs, re, opts, flags.wordBoundary)
	}
	return writeFiles(inputs, re, opts, flags.wordBoundary)
}

func compilePattern(opts cliOptions) (*regexp.Regexp, regexFlags, error) {
	flags := parseRegexFlags(opts.flags)
	pattern := opts.find
	if detectsLookAround(pattern) {
		return nil, flags, fmt.Errorf("invalid regex %s", lookAroundError(pattern))
	}
	if opts.fixedStrings {
		pattern = regexp.QuoteMeta(pattern)
	} else {
		pattern = normalizeNumericEscapes(pattern)
	}

	var prefix strings.Builder
	if flags.caseInsensitive {
		prefix.WriteString("(?i)")
	}
	if flags.multiLine {
		prefix.WriteString("(?m)")
	} else {
		prefix.WriteString("(?-m)")
	}
	if flags.dotMatchesNL {
		prefix.WriteString("(?s)")
	}

	re, err := regexp.Compile(prefix.String() + pattern)
	if err != nil {
		return nil, flags, fmt.Errorf("invalid regex %s", normalizeRegexpError(err))
	}
	return re, flags, nil
}

func parseRegexFlags(raw string) regexFlags {
	flags := regexFlags{multiLine: !strings.Contains(raw, "e")}
	for _, flag := range raw {
		switch flag {
		case 'c':
			flags.caseInsensitive = false
		case 'i':
			flags.caseInsensitive = true
		case 's':
			flags.dotMatchesNL = true
		case 'w':
			flags.wordBoundary = true
		}
	}
	return flags
}

func loadFiles(paths []string) ([]fileInput, error) {
	for _, path := range paths {
		if _, err := os.Stat(path); err != nil {
			if errors.Is(err, os.ErrNotExist) {
				return nil, fmt.Errorf("invalid path: %s", path)
			}
			return nil, errors.New(formatOSError(err))
		}
	}

	inputs := make([]fileInput, 0, len(paths))
	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			return nil, errors.New(formatOSError(err))
		}
		if info.IsDir() {
			return nil, errors.New("No such device (os error 19)")
		}

		contents, err := os.ReadFile(path)
		if err != nil {
			return nil, errors.New(formatOSError(err))
		}
		inputs = append(inputs, fileInput{path: path, contents: contents})
	}
	return inputs, nil
}

func replaceAll(re *regexp.Regexp, input []byte, opts cliOptions, requireWholeWord bool) []byte {
	matches := re.FindAllSubmatchIndex(input, -1)
	if len(matches) == 0 {
		return append([]byte(nil), input...)
	}

	template := []byte(opts.replaceWith)
	var out []byte
	last := 0
	replaced := 0

	for _, match := range matches {
		start, end := match[0], match[1]
		if requireWholeWord && !isWholeWordMatch(input, start, end) {
			continue
		}
		if opts.maxReplacements != 0 && replaced >= opts.maxReplacements {
			break
		}

		out = append(out, input[last:start]...)
		if opts.fixedStrings {
			out = append(out, template...)
		} else {
			out = re.Expand(out, template, input, match)
		}
		last = end
		replaced++
	}

	if replaced == 0 {
		return append([]byte(nil), input...)
	}

	out = append(out, input[last:]...)
	return out
}

func writePreview(inputs []fileInput, re *regexp.Regexp, opts cliOptions, requireWholeWord bool) error {
	for i, input := range inputs {
		if len(inputs) > 1 {
			if _, err := fmt.Fprintf(os.Stdout, "----- FILE %s -----\n", input.path); err != nil {
				return errors.New(formatOSError(err))
			}
		}

		output := replaceAll(re, input.contents, opts, requireWholeWord)
		if _, err := os.Stdout.Write(output); err != nil {
			return errors.New(formatOSError(err))
		}

		if i == len(inputs)-1 {
			continue
		}
	}
	return nil
}

func writeFiles(inputs []fileInput, re *regexp.Regexp, opts cliOptions, requireWholeWord bool) error {
	for _, input := range inputs {
		output := replaceAll(re, input.contents, opts, requireWholeWord)
		if err := os.WriteFile(input.path, output, 0); err != nil {
			return errors.New(formatOSError(err))
		}
	}
	return nil
}

func isWholeWordMatch(input []byte, start, end int) bool {
	return !isWordBefore(input, start) && !isWordAfter(input, end)
}

func isWordBefore(input []byte, index int) bool {
	if index <= 0 {
		return false
	}
	r, size := utf8.DecodeLastRune(input[:index])
	if r == utf8.RuneError && size == 1 {
		return false
	}
	return isWordRune(r)
}

func isWordAfter(input []byte, index int) bool {
	if index >= len(input) {
		return false
	}
	r, size := utf8.DecodeRune(input[index:])
	if r == utf8.RuneError && size == 1 {
		return false
	}
	return isWordRune(r)
}

func isWordRune(r rune) bool {
	if r == '_' || r == '\u200c' || r == '\u200d' {
		return true
	}
	if unicode.IsLetter(r) || unicode.IsDigit(r) || unicode.IsNumber(r) {
		return true
	}
	return unicode.In(r, unicode.Mn, unicode.Mc, unicode.Me, unicode.Pc)
}

func splitLongOption(arg string) (string, string, bool) {
	trimmed := strings.TrimPrefix(arg, "--")
	if idx := strings.IndexByte(trimmed, '='); idx >= 0 {
		return trimmed[:idx], trimmed[idx+1:], true
	}
	return trimmed, "", false
}

func parseMaxReplacements(value string) (int, error) {
	if value == "" {
		return 0, errors.New("invalid digit found in string")
	}
	for _, ch := range value {
		if ch < '0' || ch > '9' {
			return 0, errors.New("invalid digit found in string")
		}
	}
	parsed, err := strconv.ParseUint(value, 10, strconv.IntSize)
	if err != nil {
		return 0, errors.New("number too large to fit in target type")
	}
	return int(parsed), nil
}

func detectsLookAround(pattern string) bool {
	for i := 0; i+2 < len(pattern); i++ {
		if pattern[i] != '(' || pattern[i+1] != '?' {
			continue
		}
		if pattern[i+2] == '=' || pattern[i+2] == '!' {
			return true
		}
		if i+3 < len(pattern) && pattern[i+2] == '<' && (pattern[i+3] == '=' || pattern[i+3] == '!') {
			return true
		}
	}
	return false
}

func lookAroundError(pattern string) string {
	idx := 0
	caretLen := 3
	for i := 0; i+2 < len(pattern); i++ {
		if pattern[i] != '(' || pattern[i+1] != '?' {
			continue
		}
		if pattern[i+2] == '=' || pattern[i+2] == '!' {
			idx = i
			caretLen = 3
			break
		}
		if i+3 < len(pattern) && pattern[i+2] == '<' && (pattern[i+3] == '=' || pattern[i+3] == '!') {
			idx = i
			caretLen = 4
			break
		}
	}
	return fmt.Sprintf("regex parse error:\n    %s\n    %s\nerror: look-around, including look-ahead and look-behind, is not supported", pattern, strings.Repeat(" ", idx)+strings.Repeat("^", caretLen))
}

func normalizeNumericEscapes(pattern string) string {
	var out strings.Builder
	backslashes := 0

	flushBackslashes := func(next byte) {
		count := backslashes
		if next >= '0' && next <= '9' && count%2 == 1 {
			count++
		}
		out.WriteString(strings.Repeat("\\", count))
		backslashes = 0
	}

	for i := 0; i < len(pattern); i++ {
		if pattern[i] == '\\' {
			backslashes++
			continue
		}
		if backslashes > 0 {
			flushBackslashes(pattern[i])
		}
		out.WriteByte(pattern[i])
	}
	if backslashes > 0 {
		out.WriteString(strings.Repeat("\\", backslashes))
	}
	return out.String()
}

func normalizeRegexpError(err error) string {
	msg := err.Error()
	if strings.HasPrefix(msg, "error parsing regexp: ") {
		return strings.TrimPrefix(msg, "error parsing regexp: ")
	}
	return msg
}

func formatOSError(err error) string {
	var pathErr *os.PathError
	if errors.As(err, &pathErr) {
		if errno, ok := pathErr.Err.(syscall.Errno); ok {
			return fmt.Sprintf("%s (os error %d)", capitalize(errno.Error()), int(errno))
		}
		return capitalize(pathErr.Err.Error())
	}

	var errno syscall.Errno
	if errors.As(err, &errno) {
		return fmt.Sprintf("%s (os error %d)", capitalize(errno.Error()), int(errno))
	}

	return capitalize(err.Error())
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	if r == utf8.RuneError && size == 0 {
		return s
	}
	return string(unicode.ToUpper(r)) + s[size:]
}

func duplicateArgumentError(binName, argument string) error {
	return fmt.Errorf("error: the argument '%s' cannot be used multiple times\n\nUsage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n", argument, binName)
}

func missingValueError(argument string) error {

func missingValueError(argument string) error {
	return fmt.Errorf("error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", argument)
}

func invalidMaxReplacementsError(value string) error {
	return fmt.Errorf("error: invalid value '%s' for '--max-replacements <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.\n", value)
}

func unexpectedArgumentError(binName, argument string) error {
	return fmt.Errorf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n", argument, argument, argument, binName)
}

func missingRequiredArgsError(binName string, opts cliOptions, count int) error {
	var missing []string
	if count == 0 {
		missing = append(missing, "  <FIND>", "  <REPLACE_WITH>")
	} else {
		missing = append(missing, "  <REPLACE_WITH>")
	}

	return fmt.Errorf("error: the following required arguments were not provided:\n%s\n\n%s\n\nFor more information, try '--help'.\n", strings.Join(missing, "\n"), requiredArgsUsage(binName, opts))
}

func requiredArgsUsage(binName string, opts cliOptions) string {
	var usage strings.Builder
	usage.WriteString("Usage: ")
	usage.WriteString(binName)
	if opts.previewSet {
		usage.WriteString(" --preview")
	}
	if opts.fixedStringsSet {
		usage.WriteString(" --fixed-strings")
	}
	if opts.maxSet {
		usage.WriteString(" --max-replacements <LIMIT>")
	}
	if opts.flagsSet {
		usage.WriteString(" --flags <FLAGS>")
	}
	usage.WriteString(" <FIND> <REPLACE_WITH> [FILES]...")
	return usage.String()
}

func shortHelp(binName string) string {
	return fmt.Sprintf(`sd v1.0.0
An intuitive find & replace CLI

Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>          The regexp or string (if using `+"`-F`"+`) to search for
  <REPLACE_WITH>  What to replace each match with. Unless in string mode, you may use captured
                  values like $1, $2, etc
  [FILES]...      The path to file(s). This is optional - sd can also read from STDIN

Options:
  -p, --preview                   Display changes in a human reviewable format (the specifics of the
                                  format are likely to change in the future)
  -F, --fixed-strings             Treat FIND and REPLACE_WITH args as literal strings
  -n, --max-replacements <LIMIT>  Limit the number of replacements that can occur per file. 0
                                  indicates unlimited replacements [default: 0]
  -f, --flags <FLAGS>             Regex flags. May be combined (like `+"`-f mc`"+`).
  -h, --help                      Print help (see more with '--help')
  -V, --version                   Print version
`, binName)
}

func longHelp(binName string) string {
	return fmt.Sprintf(`sd v1.0.0
An intuitive find & replace CLI

Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using `+"`-F`"+`) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like `+"`-f mc`"+`).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make `+"`.`"+` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
`, binName)
}
